      var closeBtn = document.getElementById("fullMenuSubscribeClose");
      var modal = document.getElementById("fullMenuModal");
      if (!form || !closeBtn) return;

      var key = "cpjrFullMenuSubscribeHidden";

      function dismiss() {
        form.hidden = true;
        if (modal) modal.classList.add("subscribe-dismissed");
        try {
          window.sessionStorage.setItem(key, "1");
        } catch (err) {}
      }

      function restore() {
        form.hidden = false;
        if (modal) modal.classList.remove("subscribe-dismissed");
        try {
          window.sessionStorage.removeItem(key);
        } catch (err) {}
      }

      try {
        if (window.sessionStorage.getItem(key) === "1") dismiss();
      } catch (err) {}

