    /*  social marquee — auto-scroll + wheel / trackpad / drag */
    (function () {
      var scroller = document.querySelector(".full-menu-social");
      var track = scroller && scroller.querySelector(".full-menu-social-track");
      var modal = document.getElementById("fullMenuModal");
      if (!scroller || !track) return;

      var reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
      var speed = 0.9;
      var carry = 0;
      var paused = false;
      var resumeTimer = 0;
      var drag = { on: false, startX: 0, startLeft: 0, moved: false };

      function halfWidth() {
        return track.scrollWidth / 2;
      }

      function wrap() {
        var half = halfWidth();
        if (!half) return;
        if (scroller.scrollLeft >= half) scroller.scrollLeft -= half;
        else if (scroller.scrollLeft < 0) scroller.scrollLeft += half;
      }

      function pauseBriefly() {
        paused = true;
        window.clearTimeout(resumeTimer);
        resumeTimer = window.setTimeout(function () {
          paused = false;
        }, 1400);
      }

      function tick() {
        window.requestAnimationFrame(tick);
        if (reduceMotion || paused || drag.on) return;
        if (modal && !modal.classList.contains("is-open")) return;
        carry += speed;
        var step = carry | 0;
        if (!step) return;
        carry -= step;
        scroller.scrollLeft += step;
        wrap();
      }

      scroller.addEventListener(
        "wheel",
        function (e) {
          if (Math.abs(e.deltaY) < 1 && Math.abs(e.deltaX) < 1) return;
          e.preventDefault();
          scroller.scrollLeft += e.deltaY + e.deltaX;
          wrap();
          pauseBriefly();
        },
        { passive: false }
      );

      scroller.addEventListener("pointerdown", function (e) {
        if (e.pointerType === "mouse" && e.button !== 0) return;
        if (e.pointerType === "touch") return;
        drag.on = true;
        drag.moved = false;
        drag.startX = e.clientX;
        drag.startLeft = scroller.scrollLeft;
        /* Don't capture yet — capturing on icon clicks blocks the link */
      });

      scroller.addEventListener("pointermove", function (e) {
        if (!drag.on) return;
        var dx = e.clientX - drag.startX;
        if (!drag.moved && Math.abs(dx) > 6) {
          drag.moved = true;
          scroller.classList.add("is-dragging");
          try {
            scroller.setPointerCapture(e.pointerId);
          } catch (err) {}
        }
        if (!drag.moved) return;
        scroller.scrollLeft = drag.startLeft - dx;
        wrap();
      });

      function endDrag() {
        if (!drag.on) return;
        var wasDrag = drag.moved;
        drag.on = false;
        scroller.classList.remove("is-dragging");
        if (wasDrag) pauseBriefly();
      }

      scroller.addEventListener("pointerup", endDrag);
      scroller.addEventListener("pointercancel", endDrag);

      scroller.addEventListener(
        "click",
        function (e) {
          if (!drag.moved) return;
          e.preventDefault();
          e.stopPropagation();
          drag.moved = false;
        },
        true
      );

      scroller.addEventListener("scroll", wrap, { passive: true });

      scroller.addEventListener(
        "touchstart",
        function () {
          paused = true;
          window.clearTimeout(resumeTimer);
        },
        { passive: true }
      );
      scroller.addEventListener("touchend", pauseBriefly, { passive: true });
      scroller.addEventListener("touchcancel", pauseBriefly, { passive: true });

      /* Pause only while hovering an icon, so the row keeps auto-scrolling otherwise */
      scroller.addEventListener("mouseover", function (e) {
        if (!e.target.closest("a")) return;
        paused = true;
        window.clearTimeout(resumeTimer);
      });
      scroller.addEventListener("mouseout", function (e) {
        var fromLink = e.target.closest("a");
        if (!fromLink) return;
        var toLink = e.relatedTarget && e.relatedTarget.closest
          ? e.relatedTarget.closest("a")
          : null;
        if (toLink && scroller.contains(toLink)) return;
        resumeTimer = window.setTimeout(function () {
          paused = false;
        }, 350);
      });

      tick();
    })();

